# all 6-frame ORF scan
def revcomp(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

stops = {"TAA","TAG","TGA"}
def orfs(s):
    out=[]
    for strand,seqs in (("+",s),("-",revcomp(s))):
        for frame in range(3):
            i=frame
            start=None
            while i+3<=len(s):
                codon=seqs[i:i+3]
                if codon=="ATG" and start is None:
                    start=i
                if codon in stops:
                    if start is not None:
                        out.append((strand, frame, start, i, i-start+3, seqs[start:i+3]))
                        start=None
                i+=3
            if start is not None:
                out.append((strand, frame, start, len(s)-1, len(s)-start, seqs[start:]))
    return out

